def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'
    if n >= 99:
        return 'D'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_c = me.count('C')
    my_d = n - my_c
    last_me, last_opp = history[-1]

    if opp_d == 0:
        if n >= 95:
            return 'D'
        if n >= 20 and n % 13 == 0:
            return 'D'
        return 'C'
    if opp_c == 0:
        return 'D'

    recent = history[-12:]
    r_opp_c = sum(1 for a, b in recent if b == 'C')
    r_len = len(recent)
    r_opp_d = r_len - r_opp_c

    if r_opp_d >= r_len - 1:
        return 'D'
    if r_opp_c >= r_len - 1:
        if n >= 30 and rng.random() < 0.06:
            return 'D'
        return 'C'

    if n >= 6:
        last6 = history[-6:]
        c_after_c = 0
        n_after_c = 0
        c_after_d = 0
        n_after_d = 0
        for i in range(n - 1):
            o_next = history[i + 1][1]
            if me[i] == 'C':
                n_after_c += 1
                if o_next == 'C':
                    c_after_c += 1
            else:
                n_after_d += 1
                if o_next == 'C':
                    c_after_d += 1
        p_c_after_d = c_after_d / n_after_d if n_after_d else 0.0
        p_c_after_c = c_after_c / n_after_c if n_after_c else 0.0
        if n_after_d >= 2 and p_c_after_d >= 0.9 and p_c_after_c >= 0.9:
            if n >= 30:
                return 'D'
            return 'C'

    if last_opp == 'D':
        if r_opp_d >= 3:
            return 'D'
        d_streak = 0
        for a, b in reversed(history):
            if b == 'D':
                d_streak += 1
            else:
                break
        if d_streak >= 2:
            return 'D'
        if opp_c * 2 >= n and rng.random() < 0.35:
            return 'C'
        return 'D'
    else:
        if r_opp_d >= 4:
            return 'D'
        if opp_d * 2 > n:
            if my_d > 0 and rng.random() < 0.25:
                return 'C'
            return 'D'
        if n >= 40 and opp_c * 4 >= n * 3:
            if rng.random() < 0.08:
                return 'D'
        return 'C'
